package com.agriconnect.analytics;import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;
@RestController @RequestMapping("/api/analytics/backfill")class BackfillController{private final JdbcClient db;private final ReadModelConsumer consumer;private final String key;private final Map<String,String>urls;BackfillController(JdbcClient d,ReadModelConsumer c,@Value("${internal.api-key}")String k,@Value("${crop.url}")String crop,@Value("${rescue.url}")String rescue,@Value("${order.url}")String order,@Value("${logistics.url}")String logistics){db=d;consumer=c;key=k;urls=Map.of("crop",crop+"/internal/analytics/crop-batches","rescue",rescue+"/internal/analytics/rescue-registrations","order",order+"/internal/analytics/orders","shipment",logistics+"/internal/analytics/shipments");}@PostMapping Map<String,Object>run(@RequestParam(defaultValue="false")boolean reset){Map<String,Integer>counts=new LinkedHashMap<>();urls.forEach((source,url)->counts.put(source,fill(source,url,reset)));return Map.of("status","COMPLETED","records",counts);}
private int fill(String source,String url,boolean reset){if(reset)db.sql("delete from backfill_checkpoints where source=:s").param("s",source).update();var checkpoint=db.sql("select next_page,completed from backfill_checkpoints where source=:s").param("s",source).query().listOfRows().stream().findFirst();if(checkpoint.isPresent()&&Boolean.TRUE.equals(checkpoint.get().get("completed")))return 0;int page=checkpoint.map(x->((Number)x.get("next_page")).intValue()).orElse(0),count=0;for(;page<10000;page++){List<Map<String,Object>>rows=RestClient.create().get().uri(url+"?page="+page+"&size=100").header("X-Internal-Api-Key",key).retrieve().body(List.class);if(rows==null||rows.isEmpty()){save(source,page,true);break;}for(Map<String,Object>row:rows){String type=switch(source){case"crop"->"CropBatchUpdated";case"rescue"->"RescueRegistrationCreated";case"order"->"OrderCreated";default->"ShipmentCreated";};String identity=source+":"+row.toString();consumer.consume(Map.of("eventId",UUID.nameUUIDFromBytes(identity.getBytes(StandardCharsets.UTF_8)),"eventType",type,"payload",row));count++;}save(source,page+1,false);}return count;}
private void save(String source,int page,boolean done){db.sql("insert into backfill_checkpoints(source,next_page,completed)values(:s,:p,:d)on conflict(source)do update set next_page=excluded.next_page,completed=excluded.completed,updated_at=now()").param("s",source).param("p",page).param("d",done).update();}}
